function resetHeader(){const toggle=document.querySelector('#nav-toggle');toggle?.setAttribute('aria-expanded','false');toggle?.setAttribute('aria-label','Open navigation');document.querySelector('.header-modern')?.classList.remove('header-hidden');updateHeaderActive()}
function updateHeaderActive(){let path=location.pathname;document.querySelectorAll('#site-navigation>a').forEach(a=>{let active=a.getAttribute('href')===path;a.classList.toggle('nav-active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});document.querySelector('.nav-menus')?.classList.toggle('nav-active',path==='/menu'||path.startsWith('/menus/')||path==='/lunch')}
let lastHeaderY=0,headerTick=0;
function syncHeader(){headerTick=0;let header=document.querySelector('.header-modern');if(!header)return;let y=window.scrollY;header.classList.toggle('header-scrolled',y>50);let isOpen=document.body.classList.contains('mobile-nav-open')||!!header.querySelector('details[open]');if(y<90||isOpen||header.contains(document.activeElement)){header.classList.remove('header-hidden')}else if(Math.abs(y-lastHeaderY)>4){header.classList.toggle('header-hidden',y>lastHeaderY)}lastHeaderY=y}
window.addEventListener('scroll',()=>{if(!headerTick)headerTick=requestAnimationFrame(syncHeader)},{passive:true});
document.addEventListener('click',e=>{if(e.target.closest('#nav-scrim')){document.body.classList.remove('mobile-nav-open');document.querySelectorAll('header details').forEach(d=>d.open=false);resetHeader()}});
document.addEventListener('keydown',e=>{if(e.key==='Tab'&&document.body.classList.contains('mobile-nav-open')){let focusable=[...document.querySelectorAll('.header-modern a,.header-modern button,.header-modern summary')].filter(el=>el.getClientRects().length);let first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
